import pytest
from unittest.mock import Mock

from your_module import retry  # replace with the module where retry is defined


class FatalBaseException(BaseException):
    pass


def test_returns_value_on_first_success():
    fn = Mock(return_value="ok")

    assert retry(fn) == "ok"

    fn.assert_called_once_with()


def test_none_return_value_is_considered_success():
    fn = Mock(return_value=None)

    assert retry(fn, max_attempts=3) is None

    fn.assert_called_once_with()


def test_retries_until_success_and_stops_before_max_attempts():
    fn = Mock(side_effect=[ValueError("temporary failure"), "ok"])

    assert retry(fn, max_attempts=5) == "ok"

    assert fn.call_count == 2


def test_succeeds_on_final_allowed_attempt():
    fn = Mock(
        side_effect=[
            ValueError("first failure"),
            RuntimeError("second failure"),
            "ok",
        ]
    )

    assert retry(fn, max_attempts=3) == "ok"

    assert fn.call_count == 3


def test_reraises_last_exception_after_exhausting_attempts():
    fn = Mock(
        side_effect=[
            ValueError("first failure"),
            RuntimeError("second failure"),
            LookupError("final failure"),
        ]
    )

    with pytest.raises(LookupError, match="final failure"):
        retry(fn)  # default max_attempts is 3

    assert fn.call_count == 3


def test_max_attempts_one_does_not_retry_after_failure():
    fn = Mock(side_effect=ValueError("failed once"))

    with pytest.raises(ValueError, match="failed once"):
        retry(fn, max_attempts=1)

    fn.assert_called_once_with()


